    "SwimlaneDiagramConfig": {
      "title": "Swimlane Diagram Config",
      "allOf": [
        {
          "$ref": "#/$defs/BaseDiagramConfig"
        }
      ],
      "description": "The object containing configurations specific for the swimlanes diagram type.\n\nSwimlanes reuses the flowchart renderer and flowchart config for shared\noptions (curve, htmlLabels, spacing, …); this block holds the knobs that\nonly affect the swimlanes layout pipeline.\n",
      "type": "object",
      "unevaluatedProperties": false,
      "properties": {
        "theme": {
          "$ref": "#/$defs/BaseDiagramConfig/properties/theme",
          "default": "redux-color",
          "x-mermaid": {
            "status": "pending"
          }
        },
        "look": {
          "$ref": "#/$defs/BaseDiagramConfig/properties/look",
          "x-mermaid": {
            "status": "ignored",
            "since": "13.0.0",
            "reason": "`look` is removed (D153): ignored, with one `LOOK_REMOVED` warning per render, whatever the diagram section.",
            "replacement": "`theme`, or the geometry and `dropShadow` theme variables"
          }
        },
        "layout": {
          "$ref": "#/$defs/BaseDiagramConfig/properties/layout",
          "default": "swimlane",
          "x-mermaid": {
            "status": "pending"
          }
        },
        "lineHops": {
          "description": "Renders edge crossings as small arcs (\"hops\") or visible gaps so that\noverlapping edges are easier to read. Set to `false` to disable. Edges\nrendered as curves are skipped to avoid corrupting the geometry.\n",
          "oneOf": [
            {
              "type": "boolean"
            },
            {
              "type": "string",
              "enum": [
                "arc",
                "gap"
              ]
            }
          ],
          "default": "arc",
          "x-mermaid": {
            "status": "pending"
          }
        },
        "ignoreCrossLaneEdges": {
          "description": "Ignores edges that cross swimlane boundaries during swimlane layer\nassignment. This can improve rank quality for diagrams with many\ncross-lane links.\n",
          "type": "boolean",
          "default": true,
          "x-mermaid": {
            "status": "pending"
          }
        },
        "optimizeRanksByCrossings": {
          "description": "Enables a crossing-aware rank optimization pass for swimlane layouts.\n",
          "type": "boolean",
          "default": true,
          "x-mermaid": {
            "status": "pending"
          }
        },
        "automaticLaneOrdering": {
          "description": "Automatically reorders top-level swimlanes with a deterministic\nweighted-linear-arrangement heuristic. Disabled by default because\nsource swimlane order can carry semantic meaning.\n",
          "type": "boolean",
          "default": false,
          "x-mermaid": {
            "status": "pending"
          }
        }
      }
    },
    "AgentflowDiagramConfig": {
      "title": "Agentflow Diagram Config",
      "allOf": [
        {
          "$ref": "#/$defs/BaseDiagramConfig"
        }
      ],
      "description": "The object containing configurations specific for the agentflow diagram type.\n\nAgentflow renders through the shared unified renderer, so it owns the same\nspacing and padding knobs a flowchart does. They live in their own block so\nthat agentflow can be tuned without moving every flowchart on the page.\n",
      "type": "object",
      "unevaluatedProperties": false,
      "properties": {
        "theme": {
          "$ref": "#/$defs/BaseDiagramConfig/properties/theme",
          "default": "redux-color",
          "x-mermaid": {
            "status": "pending"
          }
        },
        "look": {
          "$ref": "#/$defs/BaseDiagramConfig/properties/look",
          "x-mermaid": {
            "status": "ignored",
            "since": "13.0.0",
            "reason": "`look` is removed (D153): ignored, with one `LOOK_REMOVED` warning per render, whatever the diagram section.",
            "replacement": "`theme`, or the geometry and `dropShadow` theme variables"
          }
        },
        "titleTopMargin": {
          "description": "Margin top for the text over the diagram",
          "type": "integer",
          "minimum": 0,
          "default": 25,
          "x-mermaid": {
            "status": "pending"
          }
        },
        "diagramPadding": {
          "description": "The amount of padding around the diagram as a whole so that embedded\ndiagrams have margins, expressed in pixels.\n",
          "type": "integer",
          "minimum": 0,
          "default": 8,
          "x-mermaid": {
            "status": "pending"
          }
        },
        "nodeSpacing": {
          "description": "Defines the spacing between nodes on the same level.\n\nPertains to horizontal spacing for TB (top to bottom) or BT (bottom to top) graphs,\nand the vertical spacing for LR as well as RL graphs.\n",
          "type": "integer",
          "minimum": 0,
          "default": 50,
          "x-mermaid": {
            "status": "pending"
          }
        },
        "rankSpacing": {
          "description": "Defines the spacing between nodes on different levels.\n\nPertains to vertical spacing for TB (top to bottom) or BT (bottom to top), and the\nhorizontal spacing for LR as well as RL graphs.\n",
          "type": "integer",
          "minimum": 0,
          "default": 50,
          "x-mermaid": {
            "status": "pending"
          }
        },
        "wrappingWidth": {
          "description": "Width of nodes where text is wrapped.\n\nWhen using markdown strings the text is wrapped automatically, this\nvalue sets the max width of a text before it continues on a new line.\n",
          "type": "number",
          "default": 120,
          "x-mermaid": {
            "status": "pending"
          }
        },
        "minNodeWidth": {
          "description": "Minimum width of the label area of a node.\n\nLabels narrower than this are widened to it, so nodes with short text\nget a uniform width; the node's own padding is added on top, the same\nway it is for `wrappingWidth`. Nodes with an explicit width are not\naffected.\n",
          "type": "number",
          "default": 120,
          "x-mermaid": {
            "status": "pending"
          }
        }
      }
    },
